-- ============================================================
-- PaMarket — Content Management Stage 2: full legal-library migration +
-- reconciliation of conflicting wording between the mobile app, the root
-- website, and the legacy www/ Capacitor shell.
--
-- Nothing already published is silently changed: every existing row's
-- current title/body/status is left exactly as Stage 1 published it. This
-- migration only:
--   1. Tags existing rows with metadata.source (documentation only).
--   2. Adds DRAFT "variant" rows for every document that has more than one
--      differing wording, tagged metadata.variantOf + metadata.source, so
--      an admin can compare them side by side and choose one (Stage 2 admin
--      UI). No variant is ever published by this migration.
--   3. Publishes the 12 mobile-only legal documents that have no
--      competing website wording at all (zero conflict, same pattern as
--      Stage 1's single-source docs).
--   4. Publishes cookie-policy from the ROOT WEBSITE wording, because that
--      is the ONLY version currently live anywhere (no page or app screen
--      currently reads a dynamic cookie-policy source) — publishing it
--      changes nothing visible. Mobile's own cookie policy wording becomes
--      a draft variant instead of being auto-applied to the app.
-- Safe to run more than once.
-- ============================================================

-- ── Tag existing Stage 1 rows with their source (no content change) ────
update public.content_pages set metadata = metadata || '{"source":"mobile-app"}'::jsonb
  where slug in ('terms','privacy','community-guidelines','refund-cancellation','public-safety','faq')
  and not (metadata ? 'source');
update public.content_pages set metadata = metadata || '{"source":"website-root"}'::jsonb
  where slug = 'account-deletion' and not (metadata ? 'source');

-- ── Reconciliation drafts: terms ─────────────────────────────
insert into public.content_pages
  (slug, content_type, title, short_description, body, status, metadata)
values (
  'terms-variant-website-root', 'legal', 'Terms of Service', 'Website root wording — differs from the published (mobile-app) version in list formatting and Section 11 payment details.',
  '{"sections":[{"heading":"","body":"These Terms of Service (\"Terms\") form a legally binding agreement between you (\"User\", \"you\") and PaMarket Zimbabwe (\"PaMarket\", \"we\", \"us\", \"our\"). By accessing or using the PaMarket mobile application or website you confirm that you have read, understood, and agree to be bound by these Terms and our Privacy Policy. If you do not agree, you must stop using the platform immediately."},{"heading":"1. Changes to These Terms","body":"We may update these Terms at any time. We will notify you of material changes by in-app notification or by posting the updated Terms with a new effective date. Your continued use of PaMarket after changes are posted constitutes your acceptance of the revised Terms. If you disagree with any change, your only remedy is to stop using the platform and delete your account."},{"heading":"2. Eligibility","body":"You must be at least 18 years old and have full legal capacity to enter into binding contracts under the laws of Zimbabwe. By creating an account you represent and warrant that you meet these requirements. We reserve the right to terminate any account we have reason to believe belongs to a person under 18, without notice or liability."},{"heading":"3. Account Registration and Security","body":"You may register using a valid email address, phone number, or a supported third-party sign-in provider (e.g. Google). You are solely responsible for maintaining the confidentiality of your password and for all activity that occurs under your account. You must notify us immediately at info@pamarketzw.com if you become aware of any unauthorised access. We will not be liable for any loss caused by someone else using your account with or without your knowledge. You may hold only one account; duplicate accounts will be removed."},{"heading":"4. Nature of the Platform - PaMarket Is a Marketplace Only","body":"PaMarket is an online classifieds and services marketplace. We provide technology that enables users to list goods, services, jobs, and business profiles, and to communicate with each other. PaMarket is not a buyer, seller, employer, employee, broker, agent, or auctioneer. We do not own, inspect, store, or ship any item listed on the platform. We do not employ, represent, endorse, or guarantee any user, business, or job poster. Any contract for the purchase or sale of any item or service is made directly between the buyer and the seller. PaMarket is not a party to any such contract."},{"heading":"5. Licence You Grant PaMarket","body":"By submitting content to PaMarket (including photos, text, videos, business names, and descriptions) you grant PaMarket a worldwide, non-exclusive, royalty-free, sublicensable, and transferable licence to use, reproduce, modify, adapt, publish, translate, distribute, and display that content across all media formats, including within the app, on our website, and for promotional purposes, for as long as the content remains on our platform. You represent and warrant that you own or have the necessary rights to grant this licence and that your content does not infringe the rights of any third party."},{"heading":"6. Listing Rules","body":"All listings must meet the following requirements: • You must own the item or have verifiable legal authority to sell it. • The title, description, photos, price, and location must accurately represent the item. No misleading statements, omissions of known defects, or inflated valuations. • All prices must be quoted in United States Dollars (USD). Listings in any other currency will be removed. • Photos must be real images of the actual item. Stock images, watermarked images, or images of a different item are not permitted. • Do not post duplicate listings for the same item across multiple categories or provinces. • Listings must be placed in the correct category. Miscategorised listings will be moved or removed. • Remove or mark your listing as sold as soon as the item is no longer available. PaMarket reserves the right to edit, reclassify, reject, or remove any listing at any time, with or without notice, for any reason including but not limited to violation of these Terms."},{"heading":"7. Prohibited Items and Content","body":"The following items, services, and types of content are strictly prohibited on PaMarket: • Stolen goods or goods obtained through fraud or deception. • Counterfeit, fake, or unauthorised copies of branded goods (replica watches, fake designer clothing, pirated software, etc.). • Goods requiring ZIMRA import permits, licences, or customs clearance that the seller does not hold. • Illegal drugs, narcotics, controlled substances, or drug paraphernalia. • Unlicensed firearms, weapons, ammunition, explosives, or related accessories. • Wildlife, live animals, animal parts, or products protected under CITES or the Zimbabwe Parks and Wildlife Act. • Tobacco products, alcohol, or spirits sold without the required ZIMRA/Government of Zimbabwe retail licence. • Pornographic, sexually explicit, or adult content of any kind. • Content that promotes or incites violence, hatred, discrimination, or terrorism on the basis of race, ethnicity, religion, gender, sexual orientation, or disability. • Pyramid schemes, multilevel marketing recruitment (MLM), advance fee fraud (419), Ponzi schemes, or any deceptive financial offer. • Impersonation of any individual, business, government body, or official institution. • Personal data or private information of third parties without their consent. • Human beings, human organs, or any service that constitutes human trafficking. • Prescription medicines or medical devices sold without a valid pharmacist or medical licence. • Hazardous chemicals, flammable materials, or radioactive substances. • Any item or service whose listing, sale, or purchase is prohibited under the laws of Zimbabwe. This list is non-exhaustive. PaMarket retains sole discretion to determine what constitutes prohibited content and to remove any content that we consider harmful, illegal, or contrary to the spirit of these Terms."},{"heading":"8. Business Shops","body":"Business accounts may create a verified Shop profile with a product catalogue and a dedicated business inbox. You must be the legitimate owner or an authorised representative of the business entity named in the Shop. All business details including name, registration status, contact information, and product listings must be accurate and kept up to date. PaMarket may request proof of business registration at any time and reserves the right to downgrade or remove verification, suspend, or permanently close any Business Shop that provides false information or violates these Terms. PaMarket does not guarantee or warrant the legitimacy, quality, or delivery of any product or service offered by a Business Shop."},{"heading":"9. Hire Talent","body":"Employers may post job openings subject to admin review, which is typically completed within 24 hours. All job postings must be for genuine, existing vacancies at a real organisation operating lawfully within Zimbabwe. Charging job seekers any registration, application, training, or placement fee is strictly prohibited and will result in immediate permanent account suspension and may be reported to the Zimbabwe Republic Police. PaMarket is not an employment agency and is not responsible for the accuracy of job descriptions, the conduct of employers, or any employment relationship that arises from a listing. Candidates use Hire Talent at their own risk and should independently verify the legitimacy of any potential employer before sharing personal information or attending an interview."},{"heading":"10. Transactions - No Involvement by PaMarket","body":"PaMarket does not facilitate, guarantee, insure, or supervise any transaction between users. We do not process payments, hold escrow funds, or provide buyer or seller protection of any kind. All agreements, payments, and deliveries are arranged directly between the buyer and the seller. PaMarket expressly disclaims any liability for: • Non-payment, partial payment, or delayed payment by a buyer. • Non-delivery, partial delivery, or late delivery of goods by a seller. • Goods that are defective, misdescribed, counterfeit, stolen, or do not match the listing. • Fraud, scams, or deceptive conduct by any user. • Loss, damage, or injury arising from a meeting between users. • Any dispute arising from a transaction conducted through or discovered on the platform."},{"heading":"11. Paid Platform Features and Payments","body":"Separately from the peer-to-peer marketplace transactions described in Section 10 above, PaMarket offers certain optional paid platform features, such as listing boosts (featured placement). Unlike buyer-seller transactions, these paid features are sold by PaMarket directly to you. • On the website (pamarketzw.com): payments for paid features are processed by Paynow (Paynow Zimbabwe), which supports EcoCash, OneMoney and bank cards. Payment is made on Paynow’s secure checkout page — PaMarket never receives or stores your card number, mobile money PIN, or bank details. We receive only a payment status and reference from Paynow so we can activate the feature you purchased. • In the mobile app: the same paid features are sold exclusively through Google Play Billing and are governed by the in-app Terms of Service and Google Play’s own terms. • Nature of purchases: boosts are one-time, consumable purchases that grant the described benefit (featured placement) for the stated duration. Purchasing a boost for a listing that is already boosted extends the existing boost — it does not run in parallel or reset it. Boosts do not renew automatically. All prices are quoted in United States Dollars (USD). • What a boost is not: a boost improves the visibility of your listing. It is not a guarantee of sale, enquiries, or approval, and it does not exempt the listing from these Terms — a boosted listing that violates these Terms may be removed without refund. • Refunds: if you were charged and your boost did not activate, or you were charged more than once for the same purchase, contact info@pamarketzw.com with your payment reference and we will activate the feature or refund the payment. Once a boost has been delivered (the featured period has started), it is non-refundable except where required by law. Cancelled or failed Paynow payments are not charged."},{"heading":"12. Messaging and User Conduct","body":"PaMarket''s in-app messaging is provided to facilitate legitimate transactions. You agree not to use messaging to send spam, unsolicited bulk messages, harassment, threats, sexually explicit content, or any content that violates these Terms. We do not read your private messages as a matter of course; however, we may review messages if they are reported to us for abuse. Do not share your bank account details, national ID numbers, passwords, or other sensitive personal information through the messaging system."},{"heading":"13. Third-Party Links and Services","body":"The platform may contain links to third-party websites, services, or resources. PaMarket has no control over the content, privacy practices, or availability of such third-party sites. A link to a third-party site does not constitute an endorsement, sponsorship, or recommendation by PaMarket. You access any third-party links entirely at your own risk. PaMarket is not responsible for any loss or damage arising from your use of third-party websites or services."},{"heading":"14. Our Intellectual Property","body":"The PaMarket name, logo, app design, user interface, proprietary software, written content, and all other intellectual property on the platform are owned by PaMarket or its licensors and are protected by copyright, trademark, and other intellectual property laws. You may not copy, reproduce, modify, distribute, create derivative works from, publicly display, or commercially exploit any part of our intellectual property without our prior written permission. Unauthorised use may result in civil and criminal liability."},{"heading":"15. Copyright and IP Infringement - Takedown Requests","body":"If you believe that content on PaMarket infringes your copyright or other intellectual property rights, please contact us in writing at info@pamarketzw.com with the following information: (a) a description of the copyrighted work or IP right you claim has been infringed; (b) the URL or location of the allegedly infringing content on PaMarket; (c) your name, address, phone number, and email; (d) a statement that you have a good-faith belief that the use is not authorised; (e) a statement that the information in your notice is accurate and that you are the rights owner or authorised to act on the owner''s behalf. We will review all valid takedown requests and act in accordance with applicable law."},{"heading":"16. Disclaimers - No Warranties","body":"TO THE FULLEST EXTENT PERMITTED BY ZIMBABWEAN LAW, PAMARKET PROVIDES THE PLATFORM \"AS IS\" AND \"AS AVAILABLE\" WITHOUT ANY REPRESENTATION OR WARRANTY OF ANY KIND, WHETHER EXPRESS, IMPLIED, OR STATUTORY, INCLUDING BUT NOT LIMITED TO WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE, TITLE, OR NON-INFRINGEMENT. WE DO NOT WARRANT THAT: (a) THE PLATFORM WILL BE UNINTERRUPTED, ERROR-FREE, SECURE, OR FREE OF VIRUSES; (b) ANY LISTING ON THE PLATFORM IS ACCURATE, COMPLETE, LEGAL, OR GENUINE; (c) THE IDENTITY OR CREDITWORTHINESS OF ANY USER HAS BEEN VERIFIED; (d) ANY ITEM OR SERVICE LISTED IS FIT FOR THE PURPOSE FOR WHICH IT IS SOLD. YOU USE THE PLATFORM ENTIRELY AT YOUR OWN RISK."},{"heading":"17. Limitation of Liability","body":"TO THE FULLEST EXTENT PERMITTED BY ZIMBABWEAN LAW, PAMARKET AND ITS OFFICERS, DIRECTORS, EMPLOYEES, AGENTS, AND LICENSORS SHALL NOT BE LIABLE TO YOU FOR ANY INDIRECT, INCIDENTAL, SPECIAL, CONSEQUENTIAL, PUNITIVE, OR EXEMPLARY DAMAGES, INCLUDING LOSS OF PROFITS, LOSS OF DATA, LOSS OF GOODWILL, OR LOSS OF BUSINESS OPPORTUNITY, ARISING OUT OF OR IN CONNECTION WITH YOUR USE OF OR INABILITY TO USE THE PLATFORM, EVEN IF WE HAVE BEEN ADVISED OF THE POSSIBILITY OF SUCH DAMAGES. OUR TOTAL AGGREGATE LIABILITY TO YOU FOR ANY CLAIM ARISING FROM OR RELATED TO THESE TERMS OR YOUR USE OF THE PLATFORM SHALL NOT EXCEED THE GREATER OF (a) THE AMOUNT YOU PAID TO PAMARKET IN THE 12 MONTHS PRECEDING THE CLAIM, OR (b) USD 10. SOME JURISDICTIONS DO NOT ALLOW THE EXCLUSION OR LIMITATION OF CERTAIN DAMAGES, SO THE ABOVE LIMITATIONS MAY NOT APPLY TO YOU IN FULL."},{"heading":"18. Indemnification","body":"You agree to defend, indemnify, and hold harmless PaMarket and its officers, directors, employees, contractors, agents, licensors, and service providers from and against any and all claims, liabilities, damages, judgments, awards, losses, costs, expenses, and fees (including reasonable legal fees) arising out of or relating to: (a) your violation of these Terms; (b) any content you post, upload, or transmit on the platform; (c) your conduct towards other users; (d) your violation of any third-party right, including intellectual property or privacy rights; (e) any transaction you enter into through or facilitated by the platform; or (f) your violation of any applicable law or regulation."},{"heading":"19. Termination","body":"PaMarket reserves the right to suspend, restrict, or permanently terminate your access to the platform at any time, with or without notice, for any reason, including but not limited to violation of these Terms, fraudulent activity, or conduct harmful to other users or to PaMarket. Upon termination, your licence to use the platform immediately ceases. You may delete your account at any time via Settings, and your data will be handled as described in our Privacy Policy. Termination does not relieve you of any obligations that arose before termination, including indemnification obligations."},{"heading":"20. Force Majeure","body":"PaMarket shall not be liable for any failure or delay in performance of its obligations under these Terms caused by circumstances beyond our reasonable control, including but not limited to internet or telecommunications failures, power outages, natural disasters, civil unrest, government actions, cyberattacks, pandemics, or acts of God. In such circumstances our obligations will be suspended for the duration of the event."},{"heading":"21. Governing Law and Dispute Resolution","body":"These Terms are governed by and construed in accordance with the laws of the Republic of Zimbabwe, without regard to its conflict of law provisions. Any dispute arising out of or in connection with these Terms shall be subject to the exclusive jurisdiction of the courts of Zimbabwe. Before commencing formal proceedings, you agree to contact us in good faith to attempt to resolve the dispute informally. We will attempt to resolve any complaint within 30 days of receipt."},{"heading":"22. Miscellaneous","body":"Entire Agreement: These Terms, together with our Privacy Policy and Community Guidelines, constitute the entire agreement between you and PaMarket and supersede all prior agreements. Severability: If any provision of these Terms is found to be unenforceable, that provision will be limited or eliminated to the minimum extent necessary so that the remaining Terms remain in full force and effect. No Waiver: Our failure to enforce any right or provision of these Terms is not a waiver of that right or provision. Assignment: You may not assign or transfer your rights under these Terms without our prior written consent. We may assign our rights without restriction. Electronic Communications: By using PaMarket you consent to receive communications from us electronically, including via in-app notifications, push notifications, and email."},{"heading":"23. Contact","body":"PaMarket Zimbabwe Email: info@pamarketzw.com WhatsApp: +971 589 772 645"}]}'::jsonb, 'draft',
  '{"variantOf":"terms","source":"website-root"}'::jsonb
)
on conflict (slug, locale) do nothing;

insert into public.content_pages
  (slug, content_type, title, short_description, body, status, metadata)
values (
  'terms-variant-website-www', 'legal', 'Terms & Conditions', 'Legacy www/ Capacitor-shell wording — appears unreferenced by any live route or deployment config; shorter and uses a different contact email (chakusaprince@gmail.com) than the current support address. Kept only because it still exists in the repo.',
  '{"sections":[{"heading":"","body":"Welcome to PaMarket Zimbabwe. By downloading or using the PaMarket app you agree to be bound by these Terms and Conditions. Please read them carefully."},{"heading":"1. Eligibility","body":"You must be at least 18 years old to create an account and use PaMarket. By registering you confirm that you meet this requirement. PaMarket reserves the right to terminate accounts of users found to be under 18."},{"heading":"2. Account Responsibility","body":"You are responsible for keeping your login credentials secure. You are liable for all activity that occurs under your account. Notify us immediately at chakusaprince@gmail.com if you suspect unauthorised access."},{"heading":"3. Listings","body":"You may only list items you own or have legal authority to sell. All listing information — including title, description, photos, and price — must be accurate and not misleading. PaMarket reserves the right to remove any listing without notice."},{"heading":"4. Prohibited Content","body":"The following are strictly prohibited on PaMarket: Stolen or counterfeit goods; illegal drugs, weapons, or firearms; adult or explicit content; hate speech or content that promotes discrimination; spam, pyramid schemes, or fraudulent offers; impersonation of any person or business."},{"heading":"5. Transactions","body":"PaMarket is a listing and communication platform only. We do not process payments, hold funds, or guarantee the quality of any item. All transactions are solely between buyer and seller. PaMarket accepts no liability for disputes, losses, or damages arising from transactions."},{"heading":"6. Intellectual Property","body":"All content you post on PaMarket (photos, descriptions, etc.) remains yours. By posting, you grant PaMarket a non-exclusive, royalty-free licence to display your content within the app. The PaMarket name, logo, and app design are our intellectual property and may not be copied or reused."},{"heading":"7. Privacy","body":"Your use of the app is also governed by our Privacy Policy, which is incorporated into these Terms by reference."},{"heading":"8. Termination","body":"We may suspend or permanently ban any account that violates these Terms, with or without notice. You may delete your account at any time via Settings → Security → Delete Account."},{"heading":"9. Limitation of Liability","body":"PaMarket is provided “as is” without warranties of any kind. To the maximum extent permitted by law, PaMarket shall not be liable for any indirect, incidental, or consequential damages arising from your use of the app."},{"heading":"10. Changes to Terms","body":"We may update these Terms from time to time. Continued use of the app after changes are posted constitutes acceptance of the revised Terms."},{"heading":"11. Governing Law","body":"These Terms are governed by the laws of Zimbabwe. Any disputes shall be resolved in the courts of Zimbabwe."},{"heading":"Contact Us","body":"Email: chakusaprince@gmail.com WhatsApp: +971 589 772 645"}]}'::jsonb, 'draft',
  '{"variantOf":"terms","source":"website-www"}'::jsonb
)
on conflict (slug, locale) do nothing;

-- ── Reconciliation drafts: privacy ───────────────────────────
insert into public.content_pages
  (slug, content_type, title, short_description, body, status, metadata)
values (
  'privacy-variant-website-root', 'legal', 'Privacy Policy', 'Website root wording — differs from the published (mobile-app) version in structure and detail level.',
  '{"sections":[{"heading":"","body":"PaMarket Zimbabwe (\"PaMarket\", \"we\", \"us\", \"our\") is committed to protecting your privacy and handling your personal information responsibly. This Privacy Policy explains what data we collect, why we collect it, how we use and protect it, who we share it with, how long we keep it, and what rights you have over it. By using PaMarket you agree to the practices described in this Policy."},{"heading":"1. Who Is the Data Controller","body":"PaMarket Zimbabwe is the data controller responsible for your personal information collected through the PaMarket mobile application and website. This Policy is governed by the Zimbabwe Cyber Security and Data Protection Act [Chapter 12:07] and applicable Zimbabwean data protection law. Contact us at info@pamarketzw.com for any privacy-related enquiry."},{"heading":"2. Information We Collect","body":"Account and identity data: your full name, email address, phone number, and profile photo when you register or update your profile. Verification data: a copy of your national ID or passport when you voluntarily request a verified badge. This document is reviewed by our admin team and permanently deleted within 30 days of the review outcome, regardless of approval or rejection. Listing data: photos, titles, descriptions, prices, categories, provinces, and suburbs you provide when posting a listing or creating a Business Shop. Business data: business name, type, description, logo, cover image, contact details, province, suburb, and product catalogue if you create a Business Shop. Job and CV data: employment history, skills, education, province, and any other information you include in a Hire Talent candidate profile or job posting. Message and communication data: the content of messages, images, offer cards, and location pins you send and receive through the in-app messaging system. Push notification token: a device token generated by Google Firebase Cloud Messaging (Android) or Apple Push Notification Service (iOS) to enable delivery of notifications about messages, listing activity, and account events. You can withdraw this permission at any time in your device Settings. Usage and behavioural data: pages viewed, search queries, listings saved or reported, categories browsed, and other in-app actions, collected to understand how users engage with the platform and to improve the service. Device and technical data: device model, operating system version, app version, IP address, and crash/error logs, used for technical troubleshooting and security monitoring."},{"heading":"3. Legal Basis for Processing","body":"We process your personal data on the following grounds: • Contract performance: to register your account, display your listings, deliver messages, and operate the core features of the platform that you have signed up for. • Legitimate interests: to detect and prevent fraud, abuse, spam, and illegal content; to improve the platform; to monitor the security of our systems; and to respond to reports of violations. • Consent: to send push notifications (you can withdraw consent at any time via device settings); to collect verification documents (voluntary and withdrawable). • Legal obligation: to comply with lawful requests from Zimbabwean authorities, including the Zimbabwe Republic Police and POTRAZ, when legally required."},{"heading":"4. How We Use Your Information","body":"• To create and manage your account and verify your identity. • To display your listings, Business Shop, candidate profile, or job postings to other users. • To deliver in-app and push notifications about messages, offers, listing status, and account events. • To moderate listings and enforce our Terms of Service and Community Guidelines. • To investigate reports of abuse, fraud, or illegal content and take enforcement action. • To improve the app''s features, design, and performance based on aggregated usage analytics. • To detect and prevent security threats, unauthorised access, and fraudulent behaviour. • To comply with legal obligations and respond to lawful requests from authorities."},{"heading":"5. Sharing and Service Providers","body":"We do not sell, rent, or trade your personal information to any third party. We share your data only with the following trusted service providers (\"sub-processors\") strictly for the purposes described: • Supabase Inc.: database hosting, user authentication, file storage, and real-time subscriptions. Data is hosted on Amazon Web Services (AWS) in the eu-west-1 (Ireland) region. • Google LLC (Firebase): Android push notification delivery via Firebase Cloud Messaging (FCM). Google receives only an anonymous device token and the notification payload; it does not receive your full profile. • Apple Inc. (APNS): iOS push notification delivery via Apple Push Notification Service. Apple receives only a device token and notification payload. • Google LLC (Sign in with Google): if you choose to register or log in using your Google account, Google shares your name and email address with us to create your PaMarket account. All sub-processors are bound by data processing agreements that prohibit them from using your data for their own purposes or sharing it with anyone else. We may also disclose your data if required to do so by a court order, warrant, or lawful request from a competent Zimbabwean authority."},{"heading":"6. Push Notifications","body":"We send push notifications to alert you to new messages, listing approvals, business enquiries, and other account activity. You can disable push notifications at any time in your device''s notification settings. Disabling notifications does not affect your ability to use the app, but you may miss time-sensitive messages from other users."},{"heading":"7. Camera, Photos, and Media","body":"The app requests permission to access your device camera and photo library only when you choose to upload photos for a listing, your profile picture, or your Business Shop logo and cover image. We do not scan your photo library or access any images beyond those you explicitly select and upload. Uploaded photos are stored in our Supabase file storage and are publicly accessible via the listing or profile where they appear."},{"heading":"8. Location Data","body":"PaMarket does not request or collect your precise GPS location automatically. Province and suburb information is entered manually by you when creating a listing or account. You may optionally share a location pin within the in-app messaging system; this pin is shared only with the specific recipient of that message."},{"heading":"9. Cookies and Analytics","body":"The PaMarket web version uses strictly necessary cookies to maintain your session. We may also work with third-party advertising vendors, including Google, who use cookies to serve ads based on your prior visits to this website or other websites. Google''s use of advertising cookies enables it and its partners to serve ads to you based on your visit to PaMarket and/or other sites on the Internet. You may opt out of personalized advertising by visiting Google''s Ads Settings, or opt out of some third-party vendor use of cookies for personalized advertising by visiting www.aboutads.info. Aggregated, anonymised usage analytics are collected within the app to understand feature usage and improve the user experience. No analytics data is linked to your name or contact details. On the PaMarket website specifically, we keep you signed in using local storage (not a tracking cookie) that is essential and cannot be switched off. Google Analytics and Google AdSense are the only optional, cookie-based technologies the website uses, and they are only loaded after you allow them in the cookie banner. See our Cookie Policy for the full list of what runs and why, and use Cookie Settings in the footer at any time to change your choice."},{"heading":"10. Data Retention","body":"• Account data: retained while your account is active. Deleted within 30 days of you requesting account deletion via Settings. • Listings: retained until you delete them or your account is closed. Deleted listings are removed from public view immediately but may remain in server logs for up to 90 days. • Messages: retained for 24 months from the date of last activity in the conversation, then automatically purged. • Verification documents: permanently deleted within 30 days of the verification review outcome. • Push notification tokens: deleted when you log out or uninstall the app. • Server and security logs: retained for 90 days for security monitoring and fraud detection, then deleted."},{"heading":"11. Security","body":"All data is transmitted using HTTPS/TLS encryption. Passwords are never stored in plain text; authentication is managed by Supabase Auth using industry-standard hashing. Our database tables are protected by row-level security (RLS) policies, which means each user can only access their own data unless they have been explicitly granted access (e.g. conversation participants). We conduct periodic security reviews and apply security patches promptly. Despite these measures, no system is completely secure. If you become aware of a security vulnerability, please report it immediately to info@pamarketzw.com. Want to delete your account? Submit a request from our Data Deletion Request page. We will process it and permanently remove your profile, listings, messages, and related data."},{"heading":"12. Your Rights and Choices","body":"• Access: you can request a copy of the personal data we hold about you by emailing us. We will respond within 30 days. • Correction: update your name, phone number, profile photo, and other details via Settings - Edit Profile at any time. • Deletion: delete your account and all associated data via Settings - Security - Delete Account. Account deletion is irreversible. • Notification opt-out: disable push notifications in your device Settings at any time. • Portability: request an export of your data in a machine-readable format by emailing us. • Withdraw consent: where processing is based on your consent (e.g. verification documents, push notifications), you may withdraw consent at any time without affecting the lawfulness of prior processing. To exercise any of these rights, contact us at info@pamarketzw.com. We will not discriminate against you for exercising your privacy rights."},{"heading":"13. International Data Transfers","body":"Your data is stored and processed by Supabase on Amazon Web Services infrastructure located in Ireland (EU). By using PaMarket you consent to this transfer. We ensure that all international transfers are subject to appropriate contractual safeguards, including Supabase''s standard data processing agreement."},{"heading":"14. Children''s Privacy","body":"PaMarket is intended for users aged 18 and over. We do not knowingly collect personal information from anyone under the age of 18. If we become aware that a user is under 18, we will delete their account and all associated data without notice. If you believe a child has registered on our platform, please contact us immediately at info@pamarketzw.com."},{"heading":"15. Marketing Communications","body":"We may occasionally send you in-app notifications about new features, platform updates, or promotional offers from PaMarket. We do not send marketing emails or SMS without your explicit opt-in. You can opt out of in-app promotional notifications by adjusting your notification preferences in Settings."},{"heading":"16. Changes to This Policy","body":"We may update this Privacy Policy from time to time to reflect changes in our practices, technology, legal requirements, or business operations. We will notify you of significant changes via an in-app notification or a prominent notice in the app. The \"Last updated\" date at the top of this Policy will always reflect the date of the most recent revision. Your continued use of PaMarket after changes are posted constitutes your acceptance of the updated Policy."},{"heading":"17. Contact","body":"For any privacy-related enquiry, request, or complaint: PaMarket Zimbabwe Email: info@pamarketzw.com WhatsApp: +971 589 772 645"}]}'::jsonb, 'draft',
  '{"variantOf":"privacy","source":"website-root"}'::jsonb
)
on conflict (slug, locale) do nothing;

insert into public.content_pages
  (slug, content_type, title, short_description, body, status, metadata)
values (
  'privacy-variant-website-www', 'legal', 'Privacy Policy', 'Legacy www/ Capacitor-shell wording — appears unreferenced by any live route or deployment config; shorter and uses a different contact email (chakusaprince@gmail.com) than the current support address. Kept only because it still exists in the repo.',
  '{"sections":[{"heading":"","body":"PaMarket Zimbabwe (“we”, “us”, or “our”) is committed to protecting your personal information. This Privacy Policy explains what data we collect, how we use it, and your rights."},{"heading":"1. Information We Collect","body":"Account data: name, email address, phone number, and profile photo when you register. Listing data: photos, descriptions, prices, and location you provide when posting an ad. Usage data: pages viewed, searches performed, listings saved, and messages sent within the app. Device data: device type, operating system, and app version for crash reporting and performance monitoring."},{"heading":"2. How We Use Your Information","body":"To operate and improve the PaMarket platform; to authenticate your account and keep it secure; to display your listings to other users; to send you notifications about messages, offers, and account activity; to investigate reports of abuse or policy violations."},{"heading":"3. Data Sharing","body":"We do not sell your personal data. We share data only with: Supabase — our database and authentication provider. Data is stored in EU data centres with encryption at rest and in transit. Google — if you choose “Sign in with Google”, your public profile is shared by Google with us. Law enforcement — when required by applicable law."},{"heading":"4. Photos & Camera","body":"The app requests access to your camera and photo library only to let you upload listing photos and a profile picture. We do not access your camera or photos for any other purpose."},{"heading":"5. Data Retention","body":"Your data is retained for as long as your account is active. When you delete your account, your personal data, listings, and messages are permanently deleted within 30 days."},{"heading":"6. Security","body":"All data is transmitted over HTTPS. Passwords are never stored in plain text — authentication is managed by Supabase using industry-standard secure hashing."},{"heading":"7. Your Rights","body":"You may access, correct, or delete your personal data at any time via Settings → Edit Profile or Settings → Security → Delete Account. You may also contact us directly to request a copy of your data."},{"heading":"8. Children''s Privacy","body":"PaMarket is not intended for users under 18. We do not knowingly collect data from children. If we become aware that a child has registered, we will delete the account immediately."},{"heading":"9. Changes to This Policy","body":"We may update this Privacy Policy from time to time. We will notify you of significant changes via in-app notification. Continued use of the app after changes are posted constitutes acceptance of the updated policy."},{"heading":"Contact Us","body":"Email: chakusaprince@gmail.com WhatsApp: +971 589 772 645"}]}'::jsonb, 'draft',
  '{"variantOf":"privacy","source":"website-www"}'::jsonb
)
on conflict (slug, locale) do nothing;

-- ── Reconciliation draft: community-guidelines (no www/ copy exists) ──
insert into public.content_pages
  (slug, content_type, title, short_description, body, status, metadata)
values (
  'community-guidelines-variant-website-root', 'legal', 'Community Guidelines', 'Website root wording — differs from the published (mobile-app) version.',
  '{"sections":[{"heading":"","body":"PaMarket is a community marketplace built on trust. These guidelines set the standards of behaviour we expect from every user - buyers, sellers, business owners, job seekers, and employers. Violating these guidelines may result in your listing being removed, your account being suspended, or a permanent ban. Serious violations may be reported to law enforcement authorities in Zimbabwe."},{"heading":"1. Listing Honesty","body":"Every listing must be honest and complete: • Only list items you physically have in your possession and have the legal right to sell. • Your title, description, and photos must accurately represent the actual condition, age, brand, model, and any known defects of the item. • Do not use manufacturer stock photos or images downloaded from the internet. Take real photos of the actual item under good lighting. • Clearly disclose any damage, scratches, faults, missing parts, or prior repairs in the description. • Remove or update your listing immediately when the item is sold, rented, or no longer available. • Do not repost the same item repeatedly to push it to the top of search results."},{"heading":"2. Prohibited Items and Services","body":"The following are never permitted on PaMarket, regardless of context or claimed purpose: • Stolen goods of any kind. • Counterfeit goods: fake branded clothing, replica watches, pirated software, unauthorised copies of any product. • Drugs and narcotics: any illegal substance, controlled drug, or drug paraphernalia. • Weapons: unlicensed firearms, illegal knives, ammunition, explosives, or weapons parts. • Wildlife: live wild animals, ivory, rhino horn, skins, or any product protected under the Zimbabwe Parks and Wildlife Act or CITES. • Adult content: pornographic images, videos, or services of any kind. • Unlicensed alcohol and tobacco sold without a valid government retail licence. • Prescription medicine sold without a valid pharmacist licence. • Financial scams: pyramid schemes, chain letters, MLM recruitment, Ponzi schemes, advance fee fraud (419), investment opportunities with guaranteed returns. • Counterfeit currency or any instrument used to commit fraud. • Rental or property listings for properties that do not exist or that the poster has no right to let. • Human trafficking or any offer of persons for sale, labour exploitation, or sexual services. • Personal data of third parties, including phone number lists, email databases, or identity documents. • Hazardous materials including toxic chemicals, flammable gases, or radioactive items."},{"heading":"3. Listing Quality Standards","body":"• Title: be specific. Include brand, model, year, size, or condition where relevant. \"2019 Samsung Galaxy S10 128GB - Excellent Condition\" is better than \"Samsung phone for sale\". • Description: write at least 3-4 sentences. Include why you are selling, the history of the item, any accessories included, and your preferred contact method. • Price: set a realistic market price in USD. Check similar listings to calibrate. \"Price negotiable\" is acceptable as a note but every listing must have a price. • Photos: upload at least 2 clear photos. Show multiple angles, include any damage, and photograph serial numbers on electronics. A listing with 5+ photos gets significantly more enquiries. • Category: choose the most specific correct category. If your item fits multiple categories, choose the primary one. • Location: select the actual province and suburb where the item is located. Do not list in a different area to attract more views."},{"heading":"4. Pricing Standards","body":"• All prices on PaMarket must be in United States Dollars (USD). This is a platform-wide rule. • Do not list items at deliberately misleading prices to attract clicks, then refuse to sell at that price. • If your price changes, update your listing immediately. • Do not attempt to collect payment in cryptocurrency, mobile money from a stranger before meeting, or any form that removes buyer protection, unless both parties have agreed in full knowledge of the risks."},{"heading":"5. Respectful Communication","body":"• Treat every user with courtesy, even if a negotiation does not go your way. • Do not send bulk or unsolicited messages. Do not use PaMarket messaging to advertise to strangers. • Do not threaten, bully, harass, intimidate, or discriminate against any user on the basis of race, ethnicity, gender, religion, sexual orientation, disability, or any other characteristic. • Do not share your bank account number, national ID, passport, or PIN through the chat. PaMarket will never ask for this information through chat. • If someone is rude, threatening, or suspicious, use the Block and Report functions. Do not engage or retaliate."},{"heading":"6. Business Shop Standards","body":"• Your Business Shop must represent a real, lawfully operating business registered or operating in Zimbabwe. • Your business name, description, logo, contact details, and product listings must all be accurate. • Do not impersonate another business, brand, or organisation. Do not use another company''s logo, name, or trademarks without written permission. • If your business changes address, phone number, or closes, update or remove your Business Shop immediately. • Featured listings in your Shop must represent products you actually stock and are ready to sell. • Do not use your Business Shop to promote pyramid schemes, MLM downlines, or financial products without appropriate licensing."},{"heading":"7. Hire Talent Standards - Employers","body":"• Job postings must be for genuine, existing vacancies at a real organisation. Fake job listings are fraud. • Never charge candidates any fee to apply, register, train, or be placed. This is illegal under Zimbabwean labour law and is grounds for immediate permanent account suspension and referral to the Zimbabwe Republic Police. • Job descriptions must be accurate regarding the role, responsibilities, remuneration, and required qualifications. • Do not post the same job multiple times to appear at the top of search results. • Mark your job as filled as soon as the vacancy is no longer open."},{"heading":"8. Hire Talent Standards - Job Seekers","body":"• Your candidate profile must be accurate. Do not misrepresent your qualifications, experience, or skills. • Do not create multiple profiles to increase visibility. • Never pay any fee to apply for a job, attend an interview, or receive a job offer. Genuine employers do not charge candidates. If asked for money, report the listing immediately."},{"heading":"9. Fraud and Scam Awareness","body":"PaMarket is a free platform and we cannot screen every user. Protect yourself: • Advance fee fraud: if a buyer asks you to send an item before receiving payment, or offers to overpay by cheque and asks you to refund the difference - this is a scam. Decline and report. • Fake rental deposits: never pay a deposit for a property before physically viewing it and verifying the landlord owns or manages it. • Too-good-to-be-true prices: a brand new iPhone for USD 50 is not a bargain, it is stolen or non-existent. Walk away. • Urgency pressure: scammers create false urgency (\"I leave the country today, pay now\"). Take your time. Legitimate sellers will wait. • Impersonation: if someone claims to be a PaMarket employee or admin asking for your password or payment, this is a scam. PaMarket will never contact you through chat asking for payment or credentials."},{"heading":"10. Safe Transactions","body":"• Always meet in a busy, public location during daylight hours. Shopping malls, filling station forecourts, and bank lobbies are recommended. • Bring a friend or family member when meeting a stranger for a high-value transaction. • Never invite a stranger to your home or travel alone to a stranger''s home for a first meeting. • Inspect and verify goods before handing over any money. • For vehicle sales, insist on a test drive and verify the log book matches the seller''s ID before paying. • For electronics, test the device fully before payment. Power it on, check IMEI against the box, verify the screen, camera, and ports work. • Trust your instincts. If something feels wrong, walk away."},{"heading":"11. Reporting Violations","body":"If you see content that violates these guidelines: • Tap the \"...\" or Report icon on the listing, profile, or message and select a reason. • For urgent safety or fraud concerns, email info@pamarketzw.com directly with as much detail as possible. • For criminal matters (stolen goods, fraud, weapons), contact the Zimbabwe Republic Police and share the listing URL with them. All reports are reviewed by our moderation team. We may not be able to share the outcome of every report with the reporter, but we act on all valid reports."},{"heading":"12. How We Enforce These Guidelines","body":"We apply a graduated enforcement approach based on the severity and frequency of violations: • Warning: first minor violation (e.g. mislabelled category, missing price). Listing is removed or corrected and you receive an in-app warning. • Temporary suspension (7-30 days): repeated minor violations or first moderate violation (e.g. misleading description, duplicate listings, disrespectful messaging). • Permanent ban: serious violations including fraud, listing illegal items, charging job seekers fees, sharing prohibited content, or any criminal activity. Permanent bans are not reversed. All listings and data are removed. • Law enforcement referral: where there is evidence of criminal activity (fraud, stolen goods, drugs, weapons, human trafficking), we will cooperate fully with the Zimbabwe Republic Police, POTRAZ, and other competent authorities, including providing user data under valid legal process."},{"heading":"13. Appeals","body":"If you believe your listing was removed or your account was actioned in error, you may appeal by emailing info@pamarketzw.com within 14 days of the action, stating your account details and the reason you believe the action was incorrect. We will review your appeal and respond within 14 business days. Appeals against permanent bans for serious violations (fraud, illegal content, criminal activity) will not be considered."},{"heading":"14. Contact","body":"PaMarket Zimbabwe Email: info@pamarketzw.com WhatsApp: +971 589 772 645"}]}'::jsonb, 'draft',
  '{"variantOf":"community-guidelines","source":"website-root"}'::jsonb
)
on conflict (slug, locale) do nothing;

-- ── Reconciliation draft: faq ─────────────────────────────────
insert into public.content_pages
  (slug, content_type, title, short_description, body, status, metadata)
values (
  'faq-variant-website-root', 'faq', 'Help & FAQ', 'Website help.html wording — 23 questions across 4 groups (Getting Started, Posting Ads, Account & Safety, Payments & Promotions), some factual details differ from the published (mobile-app) 12-question version (e.g. ad review time, listing duration, active-listing limit).',
  '{"items":[{"group":"Getting Started","q":"What is PaMarket?","a":"PaMarket is Zimbabwe''s free online marketplace and classifieds app. It lets anyone in Zimbabwe buy, sell, rent property or vehicles, find jobs, and hire talent — all in one place, with no listing fees or commissions on sales."},{"group":"Getting Started","q":"Who is PaMarket for?","a":"PaMarket is for anyone in Zimbabwe buying or selling goods, property or vehicles; job seekers and employers; and business owners who want a free online shop. It serves individual users, small businesses, and rental vehicle companies across all ten provinces."},{"group":"Getting Started","q":"How is PaMarket different from other classifieds sites?","a":"PaMarket charges zero listing fees and zero commission on any sale, unlike platforms that charge to post or take a cut of transactions. It is built specifically for Zimbabwe, covering all ten provinces with local pricing in USD and direct WhatsApp contact between buyers and sellers."},{"group":"Getting Started","q":"How do I create an account?","a":"Download the PaMarket app and tap Sign In, then Register. Fill in your name, email, phone number, and a password. Your account is ready instantly with no email verification required to start browsing."},{"group":"Getting Started","q":"Is PaMarket free to use?","a":"Yes. Posting and browsing on PaMarket is always 100% free. There are no hidden fees, listing costs, or commissions on sales. We offer optional paid promotions (Featured and Sponsored listings) to increase visibility, but these are entirely optional."},{"group":"Getting Started","q":"What areas does PaMarket cover?","a":"PaMarket covers all ten provinces of Zimbabwe with hundreds of suburbs and towns: Harare, Bulawayo, Chitungwiza, Mutare, Gweru, Kwekwe, Kadoma, Masvingo, Hwange, Chinhoyi, Norton, Marondera, Ruwa, Beitbridge, Victoria Falls, Kariba, and many more."},{"group":"Getting Started","q":"Which app platforms are supported?","a":"PaMarket is available on the Apple App Store for iPhone and iPad, and as an Android app on Google Play. You can also use PaMarket in any web browser."},{"group":"Posting Ads","q":"How do I post an ad?","a":"Tap the Post Free Ad button. Choose your category, fill in the listing title, description, price in USD, and location, then add photos. Once submitted, your ad is reviewed by our team and usually goes live within 24 hours."},{"group":"Posting Ads","q":"Why was my ad rejected?","a":"Ads must follow our Community Guidelines. Common reasons for rejection: inaccurate or misleading descriptions, prohibited items (weapons, counterfeit goods, drugs), duplicate listings, or missing key details. You can resubmit after making corrections."},{"group":"Posting Ads","q":"How long do ads stay active?","a":"Ads are active for 90 days from the date of approval. After 90 days they expire automatically. You can repost the same ad for free to keep it visible."},{"group":"Posting Ads","q":"Can I post multiple ads?","a":"Yes. You can have up to 10 active listings per account at any time. If you need more, contact us at support@pamarketzw.com and we will be happy to assist."},{"group":"Posting Ads","q":"How do I post a property listing?","a":"Tap Post Free Ad and choose the Property category. Select whether it''s for sale or rent, add the property type, province and suburb, price in USD, and at least one clear photo. Property ads are reviewed and usually go live within 24 hours."},{"group":"Posting Ads","q":"How do I sell a vehicle on PaMarket?","a":"Tap Post Free Ad and choose the Vehicles category. Add the make, model, year, mileage and condition, set your price in USD, and upload clear photos from multiple angles. Rental companies list vehicles differently — see Vehicle Rental for details."},{"group":"Posting Ads","q":"How do I contact a seller?","a":"Open any listing and tap the WhatsApp or Chat button to message the seller directly. Their contact details are never shared publicly — you connect only when you choose to reach out through the listing."},{"group":"Posting Ads","q":"How do I report a listing?","a":"Open the listing and tap the Report button (or the \"...\" menu), then choose a reason such as scam, prohibited item, or misleading information. Our moderation team reviews every report within 24 hours."},{"group":"Account & Safety","q":"How do I get a verified badge?","a":"Verified status signals to buyers that you are a trusted seller. Go to Settings, Profile, and follow the identity verification steps. You will need a valid Zimbabwe national ID or passport. Verification is reviewed within 1 to 2 business days."},{"group":"Account & Safety","q":"How do I report a suspicious listing?","a":"Tap the Report button on any listing. Select the reason for reporting and submit. Our moderation team reviews all reports within 24 hours. You can also email support@pamarketzw.com directly."},{"group":"Account & Safety","q":"I forgot my password. How do I reset it?","a":"Tap Sign In, then Forgot Password? Enter your registered email address and we will send you a reset link. The link expires after 1 hour. If you do not receive the email within a few minutes, check your spam folder."},{"group":"Account & Safety","q":"How do I stay safe when meeting buyers or sellers?","a":"Always meet in a public place during daylight hours. Never pay in advance without inspecting the item in person. Bring a friend for high-value transactions. Do not share personal financial details. If something feels suspicious, report the listing and trust your instincts."},{"group":"Account & Safety","q":"How do I delete my account?","a":"Visit our Delete Account page, or go to Settings, then Security, then Delete Account in the app. Your account and all associated data will be permanently deleted within 30 days. This action cannot be undone."},{"group":"Payments & Promotions","q":"How much do Featured or Sponsored listings cost?","a":"Featured listings cost $5 per listing per month and appear pinned at the top of search results. Sponsored listings cost $15 per listing per month and are inserted across browse results with a highlighted border. Contact us to activate a promotion for your ad."},{"group":"Payments & Promotions","q":"Does PaMarket take a commission on sales?","a":"No. PaMarket is a free platform that connects buyers and sellers. We do not process payments or take commission on any transaction. All payments are handled directly between buyer and seller."},{"group":"Payments & Promotions","q":"What payment methods do you accept for promotions?","a":"For promotional packages we accept EcoCash, OneMoney, Zimswitch, and USD bank transfer. Contact our team at support@pamarketzw.com or WhatsApp +971 58 977 2645 for payment details."}]}'::jsonb, 'draft',
  '{"variantOf":"faq","source":"website-root"}'::jsonb
)
on conflict (slug, locale) do nothing;

