insert into public.content_pages
  (slug, content_type, title, short_description, body, status, effective_date, published_at, metadata)
values (
  'cookie-policy', 'legal', 'Cookie Policy',
  'What cookies and local storage the PaMarket website uses.',
  '{"sections":[{"heading":"","body":"This Cookie Policy explains what cookies and similar local storage technologies the PaMarket website (pamarketzw.com) uses, why we use them, and how you can accept, reject or change your choice at any time. It only documents technologies that are actually present on the website — nothing here is speculative."},{"heading":"1. What Cookies Are","body":"A cookie is a small piece of data a website can ask your browser to store and send back on later requests. Modern browsers also offer similar client-side storage — localStorage and sessionStorage — which stays on your device but, unlike a cookie, is never automatically sent to a server. This Policy covers both, since the effect for you (data kept on your device between visits) is the same."},{"heading":"2. How PaMarket Uses Them","body":"PaMarket uses four categories of cookies and local storage, matching the choices available in Cookie Settings (footer link, every page):"},{"heading":"3. Essential (always active)","body":"Required for the website to function — you cannot opt out of these without breaking basic functionality, and Zimbabwean and international cookie law does not require consent for them. On PaMarket these are: Name — Type — Purpose | pm_session — localStorage — Keeps you signed in between page loads and browser sessions. This is how PaMarket implements Supabase authentication on the website — no separate Supabase cookie is set. | pm_return_url, pm_pkce_verifier, pm_recovery_token — sessionStorage — Short-lived values used only while you''re actively signing in, signing up, using \"Sign in with Google/Apple\", or resetting your password. Cleared once sign-in completes. | Sign-in attempt counter — sessionStorage — Temporarily rate-limits repeated failed sign-in attempts on the same device, as a fraud/abuse safeguard. | pamarket_cookie_consent — localStorage — Remembers the cookie choice you make on this website, so we don''t ask again on every visit. | pm_dismissed_announcement — localStorage — Remembers that you closed a site announcement banner, so it doesn''t reappear on your next page view. | pm_home_stats — localStorage — A short-lived local cache of public homepage statistics (e.g. listing counts), purely to avoid an extra request — no personal data. | Notification preferences — localStorage — When you''re signed in and change your notification toggles in Account Settings, your choice is cached on your device so the page reflects it instantly. Tied to your account, not to advertising."},{"heading":"4. Analytics — off until you allow it","body":"Used to understand traffic, page views and how people use PaMarket, so we can improve it. Name — Type — Purpose | Google Analytics (_ga and related cookies) — Cookie, set by Google — Counts visits and page views and reports aggregate usage patterns. Google Analytics'' script is not loaded on the page at all until you choose \"Accept All\" or switch Analytics on in Cookie Settings."},{"heading":"5. Preferences — off until you allow it","body":"Used for optional personalisation. Name — Type — Purpose | pm_recent — localStorage — Remembers listings you''ve recently viewed, so we can show a \"Recently viewed\" strip on listing pages. First-party only — never shared with anyone."},{"heading":"6. Marketing — off until you allow it","body":"Used to show advertising on PaMarket. Name — Type — Purpose | Google AdSense — Cookie, set by Google — Displays ads on PaMarket pages. Google may use its own cookies to select and measure ads. The AdSense script is not loaded on the page at all until you choose \"Accept All\" or switch Marketing on in Cookie Settings."},{"heading":"7. Third Parties","body":"The only third parties that can set a cookie on the PaMarket website are Google Analytics (Analytics category) and Google AdSense (Marketing category), and only after you''ve allowed that category. PaMarket does not use Meta/Facebook Pixel, TikTok Pixel, LinkedIn Insight Tag, or any other advertising or tracking script — if that changes in future, this Policy and Cookie Settings will be updated first. Links to WhatsApp, Facebook, Instagram, X, TikTok and LinkedIn appear in the site footer and on listings — these simply open those services'' own websites or apps in a new tab and do not place any cookie on pamarketzw.com."},{"heading":"8. How Long We Keep Your Choice","body":"Your cookie choice is stored on your device only (in localStorage, under the key pamarket_cookie_consent) and is not sent to our servers. It applies until you change it in Cookie Settings, clear your browser''s site data, or switch devices/browsers — each of those starts you back at a fresh choice. If we materially change what this Policy covers, we will update the stored consent''s version number, which asks you to choose again the next time you visit."},{"heading":"9. How to Change Your Choice","body":"Open Cookie Settings — click \"Cookie Settings\" in the footer of any page, at any time, to review or change your Essential, Analytics, Preferences and Marketing choices and save a new preference. You can also control cookies through your browser: most browsers let you view, delete or block cookies from their Settings/Privacy menu, and you can browse in a private/incognito window to avoid saving any of them. Blocking essential storage in your browser may prevent you from signing in or using parts of PaMarket that depend on it."},{"heading":"10. More Information","body":"For how we handle your personal data more broadly — account information, listings, messages, and your rights — see our Privacy Policy. For the rules of using PaMarket, see our Terms of Service. For any question about this Cookie Policy, contact us at support@pamarketzw.com."}]}'::jsonb,
  'published', '2026-08-08', now(),
  '{"source":"website-root"}'::jsonb
)
on conflict (slug, locale) do nothing;

insert into public.content_pages
  (slug, content_type, title, short_description, body, status, metadata)
values (
  'cookie-policy-variant-mobile-app', 'legal', 'Cookie & Data Policy', 'Mobile app wording (lib/legal.ts COOKIE_DATA_POLICY) — describes app-side local storage rather than website cookies; kept separate rather than merged.',
  '{"sections":[{"heading":"","body":"This Cookie & Data Policy explains what data PaMarket stores on your device, how we use it, and the controls you have. PaMarket is a mobile-first app — we primarily use device local storage rather than browser cookies."},{"heading":"1. What We Store Locally","body":"Auth session token — keeps you signed in — stored until sign out or expiry. App preferences (theme, language, notification settings) — stored until changed. Recently viewed listings — stored until cleared. Recent searches — stored until cleared. Cached listing data (faster loading, reduced data use) — stored until app restart."},{"heading":"2. Analytics & Performance","body":"We collect anonymised usage data to understand how the app is used and where we can improve. This includes: screen views and navigation paths (no personal data attached); error logs to diagnose app crashes and failures; performance metrics — load times, network latency; feature usage counts — e.g. how many times the search is used. This data is aggregated and cannot identify individual users."},{"heading":"3. Session Management","body":"Your authentication session is managed by Supabase, our backend provider. Sessions automatically expire after 7 days of inactivity. You can end your session at any time by signing out. For security, we may terminate sessions that show signs of compromise without notice."},{"heading":"4. Third-Party Services","body":"We use these services that may process data: Supabase — authentication, database, and file storage (ISO 27001 compliant); Cloudflare R2 — image and document storage (encrypted at rest); Firebase Cloud Messaging — push notifications on Android (optional); Cloudflare CDN — content delivery and DDoS protection. Each service operates under its own privacy policy. We select providers that comply with GDPR and modern data protection standards."},{"heading":"5. What We Do Not Do","body":"We never: sell your data to advertisers or data brokers; use third-party advertising trackers or retargeting pixels; share your personal information with other PaMarket users without your consent; use fingerprinting, cross-device tracking, or behavioural profiling for advertising."},{"heading":"6. Your Controls","body":"Clear recently viewed: Account → My Activity → Clear. Clear search history: Account → My Activity → Clear all. Sign out: ends your session and clears local auth token. Delete account: Settings → Security → Delete Account — permanently removes all your data from our servers within 30 days."},{"heading":"7. User Consent","body":"By continuing to use PaMarket you consent to the local storage practices described in this policy. For significant changes to how we handle your data, we will notify you via an in-app notification before the change takes effect. Questions? Email support@pamarketzw.com"}]}'::jsonb, 'draft',
  '{"variantOf":"cookie-policy","source":"mobile-app"}'::jsonb
)
on conflict (slug, locale) do nothing;

-- ── 12 mobile-only documents (no website equivalent, no conflict) ──
insert into public.content_pages
  (slug, content_type, title, short_description, body, status, effective_date, published_at, metadata)
values (
  'acceptable-use-policy', 'legal', 'Acceptable Use Policy', 'Rules for acceptable use of the PaMarket platform.',
  '{"sections":[{"heading":"","body":"This Acceptable Use Policy (\"AUP\") defines what you may and may not do on PaMarket. It applies to all users — buyers, sellers, employers, and visitors. Violations may result in content removal, account suspension, or referral to law enforcement."},{"heading":"1. Prohibited Listings","body":"You may not list, offer, or facilitate the sale of: illegal drugs, controlled substances, or drug paraphernalia; unlicensed firearms, weapons, ammunition, or explosives of any kind; stolen goods or items obtained through fraud or theft; counterfeit, pirated, or trademark-infringing products; human beings, human organs, or exploitation services; protected wildlife, endangered species, or their products; prescription medicines or medical devices without proper authority; alcohol or tobacco products sold to anyone under 18; any item whose sale is prohibited under Zimbabwean law."},{"heading":"2. Prohibited Conduct","body":"You may not: post false, misleading, or deceptive listings or descriptions; impersonate any person, business, government official, or authority; harvest, scrape, or collect other users'' personal data without consent; send spam, unsolicited commercial messages, or bulk automated messages; attempt to bypass, disable, or circumvent any security or verification feature; use PaMarket to facilitate money laundering, hawala transfers, or financial fraud; create multiple accounts to circumvent a ban or platform restrictions; interfere with, disrupt, or place excessive load on PaMarket servers; charge job seekers any fee to apply, register, train, or be placed — this is illegal under Zimbabwean labour law."},{"heading":"3. Content Standards","body":"All content you post must: be accurate and not misleading in any material way; not contain hate speech, discriminatory language, or incitement to violence; not contain pornographic, explicit, or violent material; not infringe any third-party intellectual property, copyright, or trademark; not contain malware, viruses, phishing links, or harmful code; not reference or advertise external competitor platforms to poach users."},{"heading":"4. Fraud Prevention","body":"PaMarket takes fraud seriously. The following are automatic grounds for permanent suspension and police referral: accepting payment for goods you do not intend to deliver; requesting advance payment for a job or service without delivery; posing as a landlord or property agent to steal rental deposits; creating fake listings to collect contact details; identity theft or impersonation of another verified user."},{"heading":"5. Enforcement Actions","body":"Violations of this AUP may result in any combination of the following: warning — for minor or first-time violations; content removal — listing removed without notice; temporary suspension — 7 to 30 days for repeated violations; permanent ban — for serious, intentional, or criminal violations; law enforcement referral — for fraud, illegal items, or criminal activity, including full cooperation with the Zimbabwe Republic Police and POTRAZ."},{"heading":"6. Reporting Violations","body":"Use the flag icon on any listing or user profile to report. Our moderation team reviews reports 7 days a week, typically within 24 hours for urgent cases. Questions? Email support@pamarketzw.com"}]}'::jsonb, 'published', '2026-07-01', now(),
  '{"source":"mobile-app"}'::jsonb
)
on conflict (slug, locale) do nothing;

insert into public.content_pages
  (slug, content_type, title, short_description, body, status, effective_date, published_at, metadata)
values (
  'buying-selling-terms', 'legal', 'Buying & Selling Terms', 'Terms specific to buying and selling on PaMarket.',
  '{"sections":[{"heading":"","body":"These Buying & Selling Terms govern all marketplace transactions on PaMarket. By posting a listing or contacting a seller you agree to these terms."},{"heading":"1. Seller Responsibilities","body":"All sellers must: own the item outright or have legal authority to sell it; list only genuine items that are physically available and in your possession; provide an accurate description including condition (new, used, damaged); upload real photos of the actual item — not stock photos or images from the internet; set a fair and honest price in USD or ZiG; disclose any known defects, damage, or faults clearly in the description; respond to buyer enquiries within a reasonable time; remove listings immediately once an item is sold; meet buyers only in a safe, public place for in-person exchanges."},{"heading":"2. Buyer Responsibilities","body":"All buyers must: inspect items thoroughly before paying — all sales are final unless otherwise agreed; never send money before seeing and verifying the item in person; negotiate respectfully — do not harass sellers with unreasonable offers; report suspicious listings using the flag icon rather than proceeding with a risky transaction; understand that PaMarket does not process or hold payments on your behalf."},{"heading":"3. Payment","body":"PaMarket does not process, hold, or guarantee any payment. All payments are arranged directly between buyer and seller. Common methods include: cash on collection (recommended for in-person meetups); EcoCash or OneMoney (verify receipt before releasing item); bank transfer (verify cleared funds before releasing item); Zipit or RTGS. Never use Western Union, gift cards, or cryptocurrency to pay for PaMarket listings. These are almost always scams."},{"heading":"4. Prohibited Items in Listings","body":"See our Acceptable Use Policy and Prohibited Items Policy for the full list. Key items you may not sell include: illegal drugs, weapons, stolen goods, counterfeit products, and any item prohibited under Zimbabwean law."},{"heading":"5. Price & Currency","body":"Listings may be priced in USD or ZiG. PaMarket displays an approximate ZiG equivalent using our published exchange rate, which is updated regularly but may not reflect the exact interbank or market rate at time of transaction. The agreed price between buyer and seller governs — PaMarket''s displayed rate is for reference only."},{"heading":"6. Listing Duration & Renewal","body":"Listings remain active for 30 days from the date of posting. You may renew any listing at any time from My Listings — this resets the 30-day timer and moves your listing back to the top. PaMarket may remove listings that violate our policies without notice or prior warning. Listings that have been inactive for 90 days may be archived automatically."},{"heading":"7. Platform Role & Liability","body":"PaMarket is a classified advertising platform. We do not inspect items, guarantee descriptions, mediate disputes, or take responsibility for the quality, legality, or safety of any item listed. All transactions are between private parties. Use good judgement and always inspect before you pay. Questions? Email support@pamarketzw.com"}]}'::jsonb, 'published', '2026-07-01', now(),
  '{"source":"mobile-app"}'::jsonb
)
on conflict (slug, locale) do nothing;

insert into public.content_pages
  (slug, content_type, title, short_description, body, status, effective_date, published_at, metadata)
values (
  'job-platform-terms', 'legal', 'Job Platform Terms', 'Terms for the Hire Talent / jobs platform.',
  '{"sections":[{"heading":"","body":"These Job Platform Terms govern use of the PaMarket jobs feature by all employers and job seekers. They supplement our main Terms of Use and are binding on all users of the jobs module."},{"heading":"1. Employer Verification","body":"Before posting a job, your company or sole trader profile must be verified. Verification requires: Certificate of Incorporation (companies) or National ID (sole traders); current ZIMRA Tax Clearance Certificate; valid photo ID of the business owner or authorised representative; a photo of the physical business premises; company name matching your ZIMRA and CRBZ registration. Verification is reviewed within 2 business days. Submitting false or doctored documents is a criminal offence and will result in permanent suspension and referral to the Zimbabwe Republic Police."},{"heading":"2. Employer Obligations","body":"As a verified employer you agree to: post only genuine vacancies that exist within your organisation; never charge job seekers any fee to apply, register, attend an interview, complete a test, purchase equipment, or be placed — this is unlawful recruitment under the Labour Act [Chapter 28:01] and grounds for immediate permanent ban and police referral; provide an honest job title, accurate salary range or \"competitive\", correct location, and clear role description; not post the same vacancy more than once in the same 30-day period; respond to applicants within a reasonable timeframe; remove or mark any vacancy as \"Filled\" within 3 days of hiring; comply with all applicable Zimbabwean employment, health and safety, and anti-discrimination law."},{"heading":"3. Job Seeker Obligations","body":"As a job seeker you agree to: provide honest and accurate information in your CV, profile, and applications; apply only for roles you genuinely intend to pursue; not submit false qualifications, certifications, or work history; not use automated bots or scripts to mass-apply to listings; treat employers with professional respect in all communications."},{"heading":"4. Anti-Scam Protection","body":"PaMarket prohibits: any job listing that directly or indirectly requests money from applicants; multi-level marketing, pyramid schemes, or commission-only recruitment disguised as employment; work-from-home schemes requiring upfront equipment or registration fees; fake company listings designed to harvest personal data; listings offering unusually high salaries for unskilled roles (a common fraud indicator). If an employer requests money from you at any stage, report it immediately using the flag icon. Do not pay. PaMarket will never contact you asking for money."},{"heading":"5. Data Handling for Job Applications","body":"When you apply for a job, your CV and contact details are shared only with the verified employer who posted the vacancy. PaMarket does not sell applicant data. Employers must not use applicant data for any purpose other than the specific vacancy applied for."},{"heading":"6. Platform Liability","body":"PaMarket is a platform connecting employers and job seekers. We do not screen candidates, guarantee employment outcomes, or act as a recruitment agency. PaMarket is not a party to any employment contract formed between an employer and a job seeker, and is not liable for any hiring decision, employment dispute, workplace injury, or loss arising from use of the jobs feature. Questions? Email support@pamarketzw.com"}]}'::jsonb, 'published', '2026-07-01', now(),
  '{"source":"mobile-app"}'::jsonb
)
on conflict (slug, locale) do nothing;

insert into public.content_pages
  (slug, content_type, title, short_description, body, status, effective_date, published_at, metadata)
values (
  'service-platform-terms', 'legal', 'Service Platform Terms', 'Terms for offering or booking services on PaMarket.',
  '{"sections":[{"heading":"","body":"These Service Platform Terms apply to all users who advertise or hire services on PaMarket, including domestic services, professional services, repairs, transport, and freelance work."},{"heading":"1. For Service Providers","body":"By advertising a service on PaMarket you agree to: provide services honestly matching your advertised description and pricing; hold any required licences, certifications, or registrations for regulated services (e.g. electrical, plumbing, medical); not quote one price and charge another without prior agreement; meet clients in a safe, agreed location for any in-person service; protect client privacy and not share personal information obtained through PaMarket; not sub-contract services to a third party without the client''s knowledge."},{"heading":"2. For Service Clients","body":"When hiring a service through PaMarket you agree to: clearly communicate your requirements before agreeing to a price; not demand services beyond what was agreed without additional payment; provide a safe working environment for service providers visiting your premises; pay in full upon satisfactory completion unless otherwise agreed in writing."},{"heading":"3. Regulated & Professional Services","body":"For services regulated under Zimbabwean law (medical, legal, financial, electrical, plumbing, security), service providers must: hold and display their relevant professional registration or licence number in their listing; ensure they have valid professional indemnity insurance where applicable; comply with all applicable professional conduct standards. PaMarket does not verify professional licences. Clients are responsible for verifying credentials before engaging any regulated service provider."},{"heading":"4. Platform Liability","body":"PaMarket provides a space for service providers and clients to connect. We do not vet, endorse, or take responsibility for the quality, legality, or safety of any service advertised. We are not liable for any loss, injury, property damage, or dispute arising from services arranged through the platform."},{"heading":"5. Prohibited Service Listings","body":"You may not advertise: illegal services of any kind; services constituting employment (use the Jobs section instead); pyramid scheme recruitment or MLM onboarding; services that violate our Acceptable Use Policy. Questions? Email support@pamarketzw.com"}]}'::jsonb, 'published', '2026-07-01', now(),
  '{"source":"mobile-app"}'::jsonb
)
on conflict (slug, locale) do nothing;

insert into public.content_pages
  (slug, content_type, title, short_description, body, status, effective_date, published_at, metadata)
values (
  'prohibited-items-policy', 'legal', 'Prohibited Items Policy', 'Items and content not allowed on PaMarket.',
  '{"sections":[{"heading":"","body":"This policy lists items that may not be bought, sold, or advertised on PaMarket under any circumstances. This list reflects Zimbabwean law, our platform values, and widely accepted marketplace standards."},{"heading":"1. Absolutely Prohibited (Zero Tolerance)","body":"These items result in immediate permanent ban and possible law enforcement referral: illegal drugs, narcotics, controlled substances, or drug paraphernalia of any kind; unlicensed firearms, prohibited weapons, ammunition, or explosives; any item related to human trafficking, forced labour, or exploitation; child sexual abuse material or any content involving minors in a sexual context; stolen goods or items obtained through criminal means; counterfeit currency, forged documents, or fake identification."},{"heading":"2. Regulated Items (Require Licence or Authority)","body":"These may be listed only if you hold the required Zimbabwean licence or authority: licensed firearms and ammunition (firearms licence required, certificate of transfer required); prescription medicines and medical devices (pharmacy or medical licence required); alcohol and tobacco products (liquor licence or trade authority required); certain agricultural chemicals and pesticides (ZAA approval required); financial products and investment schemes (SEC Zimbabwe registration required); land and property (estate agent registration with REIVAZ required for agents)."},{"heading":"3. Counterfeit & Intellectual Property Violations","body":"Counterfeit branded goods (fake Nike, Adidas, Apple, Samsung, etc.). Pirated software, films, music, or games on any media. Products using another brand''s trademarked logos or marks without authorisation. Replica luxury goods presented as genuine."},{"heading":"4. Animals & Wildlife","body":"Protected wildlife and endangered species, or their parts/derivatives. Live animals without proof of legal breeding, vaccination records, and health certificates. Ivory, rhino horn, or any product derived from protected CITES-listed animals. Pets that were obtained through illegal trapping or import."},{"heading":"5. Digital & Online Items","body":"Hacking tools, malware, exploit kits, or stolen account credentials. Fake social media accounts, followers, likes, or engagement services. Personal data dumps, email lists obtained without consent. Virtual currency or in-game items from games that prohibit real-money trading."},{"heading":"6. Reporting Prohibited Items","body":"If you see a prohibited item listed on PaMarket, tap the flag icon on the listing to report it. Our moderation team reviews reports 7 days a week. For urgent cases involving illegal weapons or human trafficking, contact the Zimbabwe Republic Police directly. Questions? Email support@pamarketzw.com"}]}'::jsonb, 'published', '2026-07-01', now(),
  '{"source":"mobile-app"}'::jsonb
)
on conflict (slug, locale) do nothing;

insert into public.content_pages
  (slug, content_type, title, short_description, body, status, effective_date, published_at, metadata)
values (
  'account-suspension-policy', 'legal', 'Account Suspension Policy', 'When and how PaMarket suspends accounts.',
  '{"sections":[{"heading":"","body":"This policy explains when and how PaMarket may suspend or permanently ban accounts, what options you have if you believe an action was taken in error, and how reinstatement works."},{"heading":"1. Grounds for Account Action","body":"PaMarket may take action on your account for: violation of our Terms of Use, Acceptable Use Policy, or Community Guidelines; posting prohibited or illegal listings; fraudulent activity or attempts to defraud other users; impersonating another person or business; creating multiple accounts to circumvent a previous ban; abusing, threatening, or harassing other users or PaMarket staff; submitting false verification documents; accumulation of confirmed complaints from other users."},{"heading":"2. Types of Account Action","body":"Warning (1st offence, minor violation) — email and in-app notification; no access restriction; listing may be removed. Listing removal — specific content removed; account remains active. Temporary suspension (7–30 days) — account locked; user cannot post, message, or apply for jobs; lifted automatically. Permanent ban — account permanently closed; all listings and data removed; user may not create a new account. Law enforcement referral — for criminal activity, PaMarket will cooperate fully with the Zimbabwe Republic Police, POTRAZ, and other competent authorities."},{"heading":"3. How We Notify You","body":"When your account is actioned, we will: send an email to your registered address explaining the reason; display an in-app notification if your account allows it; for permanent bans, send a detailed explanation by email within 48 hours."},{"heading":"4. Appealing an Account Action","body":"If you believe your account was suspended in error: email support@pamarketzw.com within 14 days of the action; include your registered email address, the date of the action, and why you believe it was incorrect; provide any relevant evidence (screenshots, receipts, communications); we will review your appeal and respond within 14 business days."},{"heading":"5. Non-Appealable Actions","body":"The following account actions cannot be appealed: permanent bans for fraud, illegal content, or criminal activity; bans for human trafficking or child exploitation material; bans for accounts confirmed by law enforcement as criminal; bans for users who have previously had a successful appeal and re-violated."},{"heading":"6. Reinstatement","body":"Temporary suspensions are lifted automatically on the stated date. No action is required from you. For temporary suspensions where the underlying violation has been resolved (e.g. a removed listing), you may contact support to request early reinstatement, which is at PaMarket''s sole discretion. Questions? Email support@pamarketzw.com"}]}'::jsonb, 'published', '2026-07-01', now(),
  '{"source":"mobile-app"}'::jsonb
)
on conflict (slug, locale) do nothing;

insert into public.content_pages
  (slug, content_type, title, short_description, body, status, effective_date, published_at, metadata)
values (
  'content-moderation-policy', 'legal', 'Content Moderation Policy', 'How PaMarket moderates listings and content.',
  '{"sections":[{"heading":"","body":"This policy explains how PaMarket moderates content, how decisions are made, and how you can engage with the moderation process."},{"heading":"1. What We Moderate","body":"PaMarket moderates: all new listings before or shortly after they go live; user-reported listings and user profiles; profile photos, business logos, and verification documents; messages flagged by our automated systems for prohibited content; job postings before activation for verified employers; reviews and ratings for fake or abusive content."},{"heading":"2. How Moderation Works","body":"Automated screening — AI-assisted systems scan listings for prohibited keywords, images, and patterns before they go live. Human review — our moderation team reviews flagged content, reported listings, and complex cases. Community reporting — users can flag any listing using the flag icon; all reports are reviewed within 24 hours. Proactive monitoring — we regularly audit categories with higher fraud rates (vehicles, property, jobs)."},{"heading":"3. Moderation Decisions","body":"When content is reviewed, we may: approve the content — no action taken; edit the listing (e.g. remove a prohibited category or correct pricing currency); request additional information from the seller; remove the listing with or without warning; suspend or permanently ban the account."},{"heading":"4. Appeals","body":"If your listing or content was removed and you believe this was incorrect, email support@pamarketzw.com within 14 days. Include the listing details and your reason for appeal. We will review and respond within 7 business days."},{"heading":"5. Transparency","body":"PaMarket publishes moderation statistics quarterly to give users insight into the health of our marketplace. These include number of listings removed per category, number of accounts banned, and fraud reports processed. Statistics are published on our website at pamarket.app. Questions? Email support@pamarketzw.com"}]}'::jsonb, 'published', '2026-07-01', now(),
  '{"source":"mobile-app"}'::jsonb
)
on conflict (slug, locale) do nothing;

insert into public.content_pages
  (slug, content_type, title, short_description, body, status, effective_date, published_at, metadata)
values (
  'reviews-ratings-policy', 'legal', 'Reviews & Ratings Policy', 'Rules for leaving and receiving reviews.',
  '{"sections":[{"heading":"","body":"Reviews and ratings on PaMarket help buyers and sellers make informed decisions. This policy governs how reviews work, what is and isn''t allowed, and how disputes are handled."},{"heading":"1. Who Can Leave a Review","body":"Any registered user who has had a genuine interaction with the reviewee (buyer/seller/employer/job seeker). Reviews should reflect your honest, first-hand experience. You may not review yourself or arrange for friends or associates to leave reviews on your behalf."},{"heading":"2. Review Standards","body":"Reviews must: be based on a genuine, direct transaction or interaction on PaMarket; be honest and reflect your actual experience; not contain personal attacks, hate speech, or discriminatory language; not include links, contact details, or promotional content; not be left in exchange for payment, a discount, or any incentive."},{"heading":"3. Prohibited Review Content","body":"Reviews will be removed if they: are fake, fabricated, or arranged by the reviewee; contain offensive, abusive, or threatening language; include defamatory statements that are untrue; are retaliatory reviews left with the intent to damage rather than inform; are duplicates of a review already left for the same transaction."},{"heading":"4. Star Rating System","body":"PaMarket uses a 1–5 star rating system: 5 stars — excellent experience, highly recommend; 4 stars — good experience with minor issues; 3 stars — average, met basic expectations; 2 stars — below expectations, significant issues; 1 star — very poor experience or suspected fraud. Your overall rating is a rolling average of all verified reviews on your profile."},{"heading":"5. Disputing a Review","body":"If you believe a review violates this policy: tap the flag icon on the review to report it; our team will review within 7 business days; reviews that violate policy will be removed — genuine honest reviews will remain even if negative; you may respond publicly to any review on your profile — responses must also comply with our content standards."},{"heading":"6. Review Manipulation","body":"Creating fake reviews, incentivising reviews, or using multiple accounts to inflate ratings is a serious violation. Confirmed manipulation will result in: removal of all manipulated reviews; reset or adjustment of the overall rating; temporary or permanent account suspension. Questions? Email support@pamarketzw.com"}]}'::jsonb, 'published', '2026-07-01', now(),
  '{"source":"mobile-app"}'::jsonb
)
on conflict (slug, locale) do nothing;

insert into public.content_pages
  (slug, content_type, title, short_description, body, status, effective_date, published_at, metadata)
values (
  'vehicle-listing-terms', 'legal', 'Vehicle Listing Terms', 'Additional terms for vehicle listings.',
  '{"sections":[{"heading":"","body":"These Vehicle Listing Terms apply to all listings in the Motors & Vehicles category on PaMarket, including cars, trucks, minibuses, motorcycles, tractors, and other motorised vehicles."},{"heading":"1. Seller Requirements","body":"To list a vehicle you must: be the registered owner of the vehicle, or have written authority from the owner to sell; ensure the vehicle is not encumbered by an unresolved finance agreement (hire purchase, bank loan) without disclosing this clearly; upload clear, real photos of the actual vehicle — minimum 4 photos including front, rear, interior, and odometer; list the accurate mileage (odometer tampering is a criminal offence); disclose all known mechanical faults, accident history, and chassis or engine modifications; hold a valid ZRP Change of Ownership (Form MVA1) or be ready to process one at sale."},{"heading":"2. Required Information","body":"Each vehicle listing must include: make, model, and year of manufacture; engine size, fuel type (petrol/diesel/electric/hybrid); transmission type (manual/automatic); accurate mileage; right-hand or left-hand drive; current condition (excellent/good/fair/for parts); price in USD (or ZiG equivalent); province and city of the vehicle''s location."},{"heading":"3. Buyer Protections","body":"Always inspect the vehicle in person before paying any deposit. Request a ZINARA (Zimbabwe National Road Administration) search to verify registration and outstanding fees. Request a police clearance to check if the vehicle is stolen. Never pay a full amount before inspecting and test-driving the vehicle. Insist on a written receipt and change of ownership form (ZRP Form MVA1) at point of sale."},{"heading":"4. Finance & Encumbered Vehicles","body":"Sellers must clearly disclose if a vehicle is under active hire purchase, bank loan, or any other financial encumbrance. Selling an encumbered vehicle without disclosure is fraud. Buyers who unknowingly purchase an encumbered vehicle may lose both the vehicle and their money."},{"heading":"5. Prohibited Vehicle Listings","body":"Vehicles with altered or removed chassis numbers (VIN/chassis tampering). Vehicles confirmed as stolen. Vehicles with tampered odometers. Write-offs presented as roadworthy without disclosure. Unlicensed vehicles being sold as roadworthy. Questions? Email support@pamarketzw.com"}]}'::jsonb, 'published', '2026-07-01', now(),
  '{"source":"mobile-app"}'::jsonb
)
on conflict (slug, locale) do nothing;

insert into public.content_pages
  (slug, content_type, title, short_description, body, status, effective_date, published_at, metadata)
values (
  'property-listing-terms', 'legal', 'Property Listing Terms', 'Additional terms for property listings.',
  '{"sections":[{"heading":"","body":"These Property Listing Terms apply to all listings in the Property & Accommodation category, including properties for sale, residential rentals, commercial lets, and short-term accommodation."},{"heading":"1. Seller & Landlord Requirements","body":"To list a property you must: be the property owner, a legally appointed agent, or have written authority from the owner; estate agents must be registered with the Real Estate Institute of Zimbabwe (REIVAZ); provide accurate photos of the actual property — not stock images or photos of a different property; disclose the accurate size, number of bedrooms/bathrooms, and all known structural or legal issues; list the correct suburb, city, and province; not list the same property multiple times simultaneously."},{"heading":"2. Rental Listings","body":"For residential and commercial rentals: state the monthly rental in USD or ZiG clearly; disclose any deposit requirements upfront (typically 1–3 months rental); specify what is and is not included (water, electricity, garden, security); specify lease duration and minimum rental period; do not collect deposits from prospective tenants until a written lease agreement is signed."},{"heading":"3. Buyer / Tenant Protections","body":"Never pay a deposit to a landlord or agent you have not met in person at the actual property. Request proof of ownership (title deeds) or the agent''s REIVAZ licence before paying anything. Insist on a written lease or sale agreement before any payment is made. Be cautious of rental prices significantly below market rate — this is a common indicator of fraud. Use the DCIP (Deeds search) to verify property ownership before purchasing."},{"heading":"4. Short-Term / Holiday Accommodation","body":"Accurately describe sleeping capacity, amenities, and condition. Clearly state all fees (cleaning fees, tourist levy, security deposit). Cancellation policy must be stated clearly in the listing. Only list properties you have the right to sub-let or advertise commercially."},{"heading":"5. Prohibited Property Listings","body":"Properties you do not own or are not authorised to sell or let. Listings designed to collect deposits for properties that do not exist or are not available. Listings for illegally sub-divided land without proper council approval. Listings misrepresenting the location or condition of a property. Questions? Email support@pamarketzw.com"}]}'::jsonb, 'published', '2026-07-01', now(),
  '{"source":"mobile-app"}'::jsonb
)
on conflict (slug, locale) do nothing;

insert into public.content_pages
  (slug, content_type, title, short_description, body, status, effective_date, published_at, metadata)
values (
  'verified-business-rules', 'legal', 'Verified Business Rules', 'Requirements for verified Business Shops.',
  '{"sections":[{"heading":"","body":"These rules apply to all businesses that have been granted Verified Business status on PaMarket. Verified status carries additional trust signals and responsibilities."},{"heading":"1. How to Get Verified","body":"Business Verification requires: Certificate of Incorporation from the Companies and Other Business Entities Act (COBE) registry; valid ZIMRA Tax Clearance Certificate (not more than 12 months old); photo ID of the authorised business representative; photo of the physical business premises with signage visible; business name matching ZIMRA and COBE registration exactly. Verification is reviewed within 2 business days. Verified status is displayed as a gold shield badge on your profile and listings."},{"heading":"2. Verified Business Privileges","body":"Gold verified badge on profile and all listings. Ability to post jobs on the PaMarket Jobs platform. Access to Business Dashboard (analytics, lead management). Priority in search results within your category. Access to Boost and Featured Listing tools. Ability to create a Business Profile page with your brand information."},{"heading":"3. Ongoing Obligations","body":"Verified businesses must: maintain a valid ZIMRA Tax Clearance Certificate — expired certificates will trigger automatic review; keep business information (address, phone, representative) current; comply with all platform rules with heightened accountability — violations by verified businesses are treated more seriously; not use the verified badge to deceive customers about the nature, scale, or credibility of your business; notify PaMarket immediately if the business changes ownership or ceases trading."},{"heading":"4. Revocation of Verified Status","body":"Verified status will be revoked for: allowing Tax Clearance Certificate to expire without renewal; fraudulent or misleading use of the verified badge; repeated Terms of Use violations; business deregistration or insolvency; confirmed fraud complaints from customers; submitting false documents at the time of verification. Revocation may be immediate and without prior warning in cases of fraud. Questions? Email support@pamarketzw.com"}]}'::jsonb, 'published', '2026-07-01', now(),
  '{"source":"mobile-app"}'::jsonb
)
on conflict (slug, locale) do nothing;

insert into public.content_pages
  (slug, content_type, title, short_description, body, status, effective_date, published_at, metadata)
values (
  'boosted-listing-rules', 'legal', 'Boosted Listing Rules', 'Rules for paid boosts and featured placement.',
  '{"sections":[{"heading":"","body":"These rules apply to all PaMarket paid platform features: listing boosts, featured slot packs, Business Shop subscriptions, Recruiter subscriptions, job posting credits, job boosts, and featured rental slots. All of these are purchased through Google Play Billing or Apple''s In-App Purchase billing and must comply with all standard listing requirements."},{"heading":"1. What Boosting Does","body":"Moves your listing to the top of search results and category pages. Adds a \"Featured\" or \"Boosted\" label to your listing card. Increases visibility in Browse and Home feeds. May include placement in the PaMarket \"Top Picks\" carousel. Duration depends on the package purchased (1, 7, or 30 days)."},{"heading":"2. Eligibility","body":"Listings must meet all of the following before a boost can be applied: listing must be Active and comply with all Terms of Use; listing must have at least one real photo; listing must have an accurate title, description, and price; listings under review or flagged for policy violations are not eligible; prohibited items may not be boosted under any circumstances."},{"heading":"3. Payment & Refunds — Platform Billing","body":"All paid features (boosts, featured slot packs, Business Shop and Recruiter subscriptions, job credits, job boosts, featured rental slots) are purchased and billed through Google Play Billing or Apple''s In-App Purchase billing using the payment method on your Google account or Apple ID — PaMarket never receives or stores your card details. One-time purchases (boosts, slot packs, job credits, job boosts, featured rental slots) activate immediately after payment confirms and expire automatically at the end of the purchased duration or once the credits are used. Subscriptions (Business Shop and Recruiter plans) renew automatically each billing period until cancelled via Google Play Store → Payments & subscriptions (Android) or Settings app → Subscriptions (iPhone) — PaMarket cannot cancel a subscription on your behalf. Refunds are requested through Google Play Store → Order history → Report a problem (Android), or reportaproblem.apple.com (iPhone) and are subject to Google Play''s or Apple''s refund policy. No refund is issued if a listing is removed for policy violations during an active boost or subscription period. If a purchase completes but the feature does not activate in the app, contact support with your Google Play or the App Store (depending on your device) order number and we will investigate and correct it."},{"heading":"4. Boost Limits","body":"Free accounts: maximum 1 boosted listing at a time. Verified businesses: additional featured slots depend on your Shop subscription tier plus any featured slot packs purchased. No listing may be kept permanently at position #1 — rotation applies to ensure fair access. Boosting does not exempt a listing from moderation or user reports."},{"heading":"5. Our Rights","body":"PaMarket reserves the right to: remove or suspend a boost or featured placement if the listing violates platform policies, even if payment has been made; adjust the boost algorithm to ensure a fair and diverse marketplace experience; refuse to boost or feature any listing at our sole discretion; direct you to Google Play or the App Store (depending on your device) for refund processing on any paid feature removed for policy violations. Questions? Email support@pamarketzw.com"}]}'::jsonb, 'published', '2026-07-01', now(),
  '{"source":"mobile-app"}'::jsonb
)
on conflict (slug, locale) do nothing;

-- Record this migration as an administrator content action.
insert into public.admin_audit_logs (action, entity, entity_id, after_state, reason)
select 'migrate_stage2_content', 'content_pages', null,
