  ), 'variant_drafts_added', (
    select jsonb_agg(slug) from public.content_pages where metadata ? 'variantOf'
  )),
  'Stage 2: migrated the 12 remaining mobile-only legal documents as published (no conflicting website wording exists), published cookie-policy from the website-root wording (the only version currently live), and added draft variant rows for every document with conflicting wording (terms, privacy, community-guidelines, faq, cookie-policy) tagged with metadata.source for admin side-by-side review. No previously published content was changed.'
where exists (select 1 from public.content_pages where slug = 'acceptable-use-policy');
